// §11.3/§5.1 yat::StateStore backed by one file per key under /state/ on the
// already-mounted LittleFS. Keys are "<packid>.<sourceid>"; PACK-SPEC's
// packid/sourceid schemas (§3/§5) already restrict those to [a-z0-9._-], so
// they're filename-safe as-is, but sanitize() still defensively substitutes
// anything outside that set — this store has no other way to reject a
// malformed key, and a stray '/' must never be allowed to escape /state/.
struct LittleFsStateStore : yat::StateStore {
  static std::string sanitize(const char* key) {
    std::string s;
    for (const char* p = key; *p; p++) {
      char c = *p;
      bool ok = (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '.' || c == '_' || c == '-';
      s += ok ? c : '_';
    }
    return s.empty() ? std::string("_") : s;
  }
  static std::string pathFor(const char* key) { return "/state/" + sanitize(key); }

  bool get(const char* key, std::string& out) override {
    return littlefsReadFile(pathFor(key).c_str(), out);
  }
  bool put(const char* key, const std::string& val) override {
    if (!LittleFS.exists("/state")) LittleFS.mkdir("/state");
    return littlefsWriteFile(pathFor(key).c_str(), val.data(), val.size());
  }
};

// Config v2 (Task A, ARCHITECTURE §4 extended): one page became 1..16.
// aliases exists in the schema now so a hand-written/migrated config.json
// round-trips through GET/PUT without losing it, but nothing matches against
// it yet — voice arrives in Task B.
struct ConfigPage {
  std::string id;
  std::string pack;
  std::string paramsJson;  // serialized params object; empty => none
  std::vector<std::string> aliases;
  int everyMin = 0;  // per-page cadence override, minutes; 0 => follow the pack's schedule
};

// config.json pages[].every_min — the user's answer to "how often should THIS
// page update", overriding the pack author's schedule (see computeSleepPlan).
// 5 min is the same platform cadence floor PACK-SPEC §12.1 puts on the pack's
// own every_min; 1440 is a day, past which this stops being a cadence.
static constexpr int PAGE_EVERY_MIN_MIN = 5;
static constexpr int PAGE_EVERY_MIN_MAX = 1440;

// config.json "voice": {"seconds": N} — how long a KEY0 tap records (PRD §4.4).
// Clamped: below 2 s nobody can finish saying "巴士幾時到", and above 8 s the
// PSRAM buffer and the upload both grow for no accuracy gain (16 kHz mono
// 16-bit = 32 KB/s, so 8 s is already a 256 KB body).
static constexpr int VOICE_SECONDS_DEFAULT = 4;
static constexpr int VOICE_SECONDS_MIN = 2;
static constexpr int VOICE_SECONDS_MAX = 8;

// config.json "loop_min" — auto-rotate: the device walks to the next page by
// itself every N minutes, so a household with four pages sees all four without
// touching a button. Absent or 0 is off, and the only other values are 30, 60
// and 180.
//
// That ladder is the product decision, not a parser convenience. Every advance
// is a full 30 s panel refresh whether or not a single number on the page
// changed, so it is paid twice: in battery, and in the panel's finite rated
// refresh count. A 5-minute rotation would spend both on pages nobody asked to
// see. So a hand-edited value off the ladder is snapped to a rung rather than
// honored — and upward within the ladder, because the floor is the whole point.
static constexpr int kLoopMinChoices[] = {30, 60, 180};

// config.json "llm_model" — which chat model the voice router asks for, on
// whichever of the two services the stored key selects. Absent is the normal
// case and leaves each provider on its own default (the `model` column of
// kLlmProviders), chosen so that which service a household ended up on is not a
// decision about quality they had to make.
//
// Deliberately config-only, with no control anywhere in the portal. Picking a
// model is a question about price and capability that the audience this product
// is built for has no way to answer and no reason to be asked; it exists for
// the household that has someone willing to edit a file, and for us when we
// want to try a different router on real hardware without a firmware build.
static constexpr size_t kLlmModelMax = 64;

struct DeviceConfig {
  std::vector<ConfigPage> pages;
  std::string quietStart, quietEnd;    // "HH:MM"; both empty => quiet hours disabled
  int voiceSeconds = VOICE_SECONDS_DEFAULT;
  bool beep = true;  // config.json "beep"; absent => true. See the beep vocabulary block.
  int loopMin = 0;   // config.json "loop_min"; 0 => no auto-rotate. See kLoopMinChoices.
  std::string llmModel;  // config.json "llm_model"; empty => the active provider's default.
};

