// ---------------- the one pack the device writes back (PRD §4.4 intents) ----------------
//
// Every other pack's params are read-only to the firmware: the household sets
// them in the portal and the device renders them. The household todo list is
// the exception — voice can add an item, mark one done, or clear the done ones
// — so these three bounds are the pack's own schema restated on the writing
// side, because the firmware is what has to refuse to exceed them.
static constexpr const char* TODO_PACK_ID = "todo";
// 20, not a number this side picked: PACK-SPEC §3.2/§12.1 hard-caps any array
// param at 20 entries, so that is what the todo pack's schema declares and
// what the portal will accept. Voice must refuse at the same number the portal
// does, or the household gets a 21st item by voice that no later save from the
// settings page will keep.
static constexpr size_t TODO_MAX_ITEMS = 20;
// Codepoints, not bytes: the schema counts characters, and 48 Chinese
// characters are 144 UTF-8 bytes. A full list is therefore ~3.5 KB of params,
// against a 64 KB config — see savePageParams()'s own ceiling check.
static constexpr size_t TODO_MAX_TEXT_CP = 48;

// Replaces pages[<pageIdx>].params in /config.json with `paramsJson`, leaving
// every other byte of the file — quiet hours, the beep switch, the other pages,
// anything a hand-edit added that this firmware has never heard of — exactly as
// it found it, and mirrors the new value into g_pages[pageIdx].paramsJson so the
// refresh THIS cycle draws it. Same write machinery the portal's apply path
// uses (littlefsWriteFile: temp file, size check, atomic rename), so an
// interruption leaves the old params or the new ones and never a half list.
bool savePageParams(int pageIdx, const std::string& paramsJson);

int loadClampedPageIdx(size_t numPages);
extern time_t g_loopOriginEpoch;
void saveLoopOrigin(time_t when);
time_t loadLoopOrigin();
void savePageIdx(int idx);

